from pyspark.sql import functions as F


def check_results(observations):
    # Step 1: one row per HbA1c result, with the first rule it breaks in `reason` (NULL when it is fine).
    value = F.col("value")
    reason = F.when(value.isNull(), "missing_value")  # add the other checks, in order
    return observations.filter(F.col("code") == "HBA1C").select("observation_id", "value", reason.alias("reason"))


def hba1c_band(checked):
    # Step 2: a band for every result that passed step 1.
    value = F.col("value")
    band = (
        F.when(F.isnan(value), None)
        .when(value < 5.7, "normal")
        .when(value < 6.5, "prediabetes")
        .when(value >= 6.5, "diabetes")
    )
    return checked.select("observation_id", "value", band.alias("band"), "reason")


def solve(observations):
    return hba1c_band(check_results(observations))
